 23→export async function POST(request: NextRequest): Promise<NextResponse> {
 24→  const secret = process.env.SENTRY_WEBHOOK_SECRET;
 25→  const githubToken = process.env.GITHUB_TOKEN_ISSUES;
 26→
 27→  const resource = request.headers.get('sentry-hook-resource');
 28→  const signature = request.headers.get('sentry-hook-signature');
 29→
 30→  // Sentry calls this endpoint to validate alert-rule-action settings
 31→  if (!resource && !signature) {
 32→    return NextResponse.json({ ok: true });
 33→  }
 34→
 35→  if (!secret || !githubToken) {
 36→    console.error('[Sentry Webhook] Missing SENTRY_WEBHOOK_SECRET or GITHUB_TOKEN_ISSUES');
 37→    return NextResponse.json({ error: 'Not configured' }, { status: 500 });
 38→  }
 39→
 40→  const body = await request.text();
 41→
 42→  if (!signature) {
 43→    return NextResponse.json({ error: 'Missing signature' }, { status: 401 });
 44→  }
 45→
 46→  // Verify HMAC-SHA256 signature using integration client secret
 47→  // TODO: Update SENTRY_WEBHOOK_SECRET to match integration client secret from Sentry UI
 48→  const expected = createHmac('sha256', secret).update(body).digest('hex');
 49→  if (signature !== expected) {
