 51→      '[Sentry Webhook] Signature mismatch — verify SENTRY_WEBHOOK_SECRET matches integration client secret'
 52→    );
 53→  }
 54→
 55→  const payload = JSON.parse(body);
 56→  const action = payload.action as string;
 57→
 58→  // Installation lifecycle events
 59→  if (resource === 'installation') {
